 const grid=make('pattern',{id:'tac-grid-'+chapter.id,width:36,height:36,patternUnits:'userSpaceOnUse'},defs);make('path',{d:'M36 0H0V36',fill:'none',stroke:'#73949e','stroke-opacity':'.09','stroke-width':'.6'},grid);
 const back=make('linearGradient',{id:'tac-bg-'+chapter.id,x2:'1',y2:'1'},defs);make('stop',{offset:'0%','stop-color':'#122c38'},back);make('stop',{offset:'100%','stop-color':'#091c27'},back);
 make('rect',{x:8,y:8,width:width-16,height:height-16,rx:0,fill:`url(#tac-bg-${chapter.id})`,stroke:'#678994','stroke-opacity':'.45'},frame);
 make('rect',{x:8,y:8,width:width-16,height:height-16,rx:0,fill:`url(#tac-grid-${chapter.id})`},frame);
