 if(spatial.layoutKind==='narrative'){
  for(const [i,r]of [110,165,235,305].entries())make('ellipse',{cx:600,cy:365,rx:r*1.48,ry:r*.86,fill:'none',stroke:i%2?'#8493b5':'#78b1ad','stroke-opacity':.2,'stroke-dasharray':i%2?'4 15':'none'},terrain);
 }else if(spatial.layoutKind==='wilderness'){
  for(let i=0;i<7;i++)make('path',{d:`M45 ${165+i*57} C240 ${20+i*63},320 ${300+i*35},530 ${150+i*65} S950 ${90+i*70},1160 ${220+i*53}`,fill:'none',stroke:'#82a5a5','stroke-width':i%3===0?2:.8,'stroke-opacity':'.14'},terrain);
 }else if(spatial.layoutKind==='interior'){
  make('path',{d:'M130 170L335 100H970L1120 260V520L900 645H245L80 490Z',fill:'#223e48','fill-opacity':'.26',stroke:'#8caba8','stroke-opacity':'.2'},terrain);
  for(let y=200;y<610;y+=100)make('path',{d:`M120 ${y}H1080`,stroke:'#90a6a8','stroke-opacity':'.1'},terrain);
 }else if([4,5].includes(chapter.id)){
  make('path',{d:'M90 360H1110',stroke:'#78989f','stroke-opacity':'.2','stroke-dasharray':'4 12'},terrain);
 }else if(chapter.id===7){
  make('path',{d:'M80 145H365V620H80Z',fill:'#29434c','fill-opacity':'.12',stroke:'#78989f','stroke-opacity':'.3','stroke-dasharray':'6 8'},terrain);make('path',{d:'M405 140L960 140 1135 350 1060 625 450 625 390 420Z',fill:'#29434c','fill-opacity':'.2',stroke:'#8aabb0','stroke-opacity':'.4'},terrain);
 }else{
  make('path',{d:chapter.id<9?'M105 215L230 115 630 98 1050 190 1120 385 975 617 640 660 260 600 80 420Z':'M120 185L380 102 980 130 1110 315 1050 590 815 650 230 590 80 390Z',fill:'#29434c','fill-opacity':'.22',stroke:'#82a6b0','stroke-opacity':'.27','stroke-width':'2'},terrain);
  // Cartographic texture, not invented roads or an administrative boundary.

 }
 label(frame,'FIELD OPERATIONS / '+String(chapter.id).padStart(2,'0'),30,37,'tac-kicker');label(frame,spatial.setting||chapter.place,30,72,'tac-title');label(frame,chapter.id===7?'并行场景分区 · 不表示龙门、罗德岛与核心城彼此相邻':'剧情地点关系图 · 示意布局，不代表测绘坐标',30,height-22,'tac-footnote');
 const places=make('g',{class:'tactical-places'},frame),links=make('g',{class:'tactical-links'},frame),actors=make('g',{class:'tactical-actors'},frame),nodes=new Map();let previous=new Map();
 for(const [i,p]of localPlaces.entries()){const g=make('g',{'data-place':p.id,class:'tactical-place'},places);const land=make('g',{class:'place-landmark','aria-hidden':'true'},g);if(/塔|核心|公爵府|大楼/.test(p.label)){make('rect',{x:p.x-29,y:p.y-66,width:58,height:42,rx:2},land);make('rect',{x:p.x-18,y:p.y-87,width:36,height:25,rx:1},land);make('path',{d:`M${p.x-44} ${p.y-22}H${p.x+44}M${p.x} ${p.y-87}V${p.y-104}`},land);}else if(/舰|舷|舱/.test(p.label)){make('path',{d:`M${p.x-65} ${p.y-55}H${p.x+48}L${p.x+69} ${p.y-35}L${p.x+42} ${p.y-20}H${p.x-56}Z`},land);}else if(/树林|冻原|荒|森林/.test(p.label)){for(const dx of [-35,0,35])make('path',{d:`M${p.x+dx} ${p.y-78}l-20 45h40Z`},land);}else{for(const [dx,dy,w,h]of [[-55,-66,32,35],[-16,-82,38,52],[29,-60,29,29]])make('rect',{x:p.x+dx,y:p.y+dy,width:w,height:h,rx:2},land);}label(g,p.label,p.x,p.y+7,'place-title');const t=make('title',{},g);t.textContent=p.basis||p.accuracy||'剧情地点，布局为阅读示意';}
 function makeActor(p){const g=make('g',{'data-actor':p.key,tabindex:0,role:'button',class:'tactical-actor'},actors);g.style.setProperty('--team-color',factionColor(p));make('ellipse',{cx:0,cy:18,rx:60,ry:14,class:'actor-ground'},g);const portraitGroup=make('g',{class:'actor-portraits'},g);const chars=(p.characters||[]).slice(0,2);const shown=chars.length?chars:[p.name||p.factionName||'小队'];shown.forEach((name,i)=>{const a=resolveImage(name),x=chars.length===2?(i===0?-30:25):0,r=i===1?30:36;make('circle',{cx:x,cy:-12,r:r+3,class:'actor-ring'},portraitGroup);const clipId=`avatar-${chapter.id}-${nodes.size}-${i}`;const clip=make('clipPath',{id:clipId},defs);make('circle',{cx:x,cy:-12,r},clip);const clipped=make('g',{'clip-path':`url(#${clipId})`},portraitGroup);if(a){const dims=a.dimensions||[180,180],box=a.focusBox||[0,0,...dims];const svg=make('svg',{x:x-r,y:-12-r,width:r*2,height:r*2,viewBox:box.join(' '),preserveAspectRatio:'xMidYMin slice'},clipped);make('image',{href:a.path,x:0,y:0,width:dims[0],height:dims[1]},svg);}else{make('circle',{cx:x,cy:-12,r,fill:'#28434e'},clipped);label(clipped,name.slice(0,2),x,-6,'actor-initial');}});make('rect',{x:-121,y:30,width:242,height:63,rx:6,class:'actor-label-bg'},g);label(g,p.name||p.factionName||p.factionId,0,55,'actor-name');label(g,shown.join(' / '),0,79,'actor-members');label(g,'',0,-62,'actor-relation');g.addEventListener('click',()=>onActor(p.key));return g;}
 function update(nodeIndex,{animate=true}={}){const node=spatial.nodes[nodeIndex],layout=arrangeMarkers(node.placements,localPlaces,compact,{width,height}),active=new Set(layout.map(p=>p.locationId)),keys=new Set(layout.map(p=>p.key));const labelLayout=arrangePlaceLabels(localPlaces,layout,{width,height});for(const g of places.children){g.classList.toggle('active',active.has(g.dataset.place));const at=labelLayout.get(g.dataset.place),text=g.querySelector('.place-title');text.style.display=at?'':'none';if(at){text.setAttribute('x',at.x);text.setAttribute('y',at.y);}}links.replaceChildren();for(const p of localPlaces){const at=labelLayout.get(p.id);if(at&&Math.hypot(at.x-p.x,at.y-p.y)>35)make('path',{d:`M${p.x} ${p.y}L${at.x} ${at.y-12}`,stroke:'#90abb5','stroke-opacity':active.has(p.id)?.6:.2,'stroke-dasharray':'3 5',fill:'none'},links);}for(const[key,g]of nodes){if(!keys.has(key)){g.style.opacity='0';g.style.pointerEvents='none';g.setAttribute('tabindex','-1');g.setAttribute('aria-hidden','true');}}
 for(const p of layout){const color=factionColor(p);const tracks=p.characters.length?p.characters.slice(0,2):[null];for(const character of tracks){const history=[];for(const previousNode of spatial.nodes.slice(0,nodeIndex+1)){const entry=previousNode.placements.find(q=>q.relation==='present'&&(character?q.characters.includes(character):q.key===p.key));if(!entry)continue;const place=localPlaces.find(l=>l.id===entry.locationId);if(place&&history.at(-1)?.id!==place.id)history.push(place);}if(p.relation==='present'&&history.length>1){const path=make('path',{d:history.map((a,i)=>`${i?'L':'M'}${a.x} ${a.y+20}`).join(' '),stroke:color,'stroke-opacity':'.32','stroke-width':2,'stroke-dasharray':'2 8',fill:'none',class:'reading-trace'},links);const title=make('title',{},path);title.textContent=(character||p.name)+'的剧情出现顺序；不代表道路或确切移动时刻';}}make('circle',{cx:p.anchor.x,cy:p.anchor.y+20,r:5,fill:color,stroke:'#102532','stroke-width':2},links);make('path',{d:`M${p.anchor.x} ${p.anchor.y+20}L${p.x} ${p.y}`,stroke:color,'stroke-opacity':'.75','stroke-width':'2','stroke-dasharray':p.relation==='present'?'none':'4 5',fill:'none',class:'actor-leader'},links);const move=p.moveFromLocationId||(p.movement?.fromLocationId),origin=localPlaces.find(l=>l.id===move);if(origin&&p.relation==='present'&&move!==p.locationId){make('path',{d:`M${origin.x} ${origin.y+20}Q${(origin.x+p.anchor.x)/2} ${Math.min(origin.y,p.anchor.y)-60} ${p.anchor.x} ${p.anchor.y+20}`,stroke:color,'stroke-width':2,fill:'none','stroke-dasharray':'5 7',class:'movement-trace','marker-end':`url(#move-arrow-${chapter.id})`,'data-movement-key':p.key},links);}
 let g=nodes.get(p.key);if(!g){g=makeActor(p);nodes.set(p.key,g);}g.style.transition=animate&&p.relation==='present'?'transform 520ms cubic-bezier(.22,.7,.25,1), opacity 260ms':'opacity 200ms';g.style.transform=`translate(${p.x}px,${p.y}px) scale(${p.size})`;g.style.opacity='1';g.style.pointerEvents='auto';g.setAttribute('tabindex','0');g.removeAttribute('aria-hidden');g.dataset.location=p.locationId;g.dataset.relation=p.relation;g.setAttribute('aria-label',`${p.name||p.factionName}：${p.anchor.label}，${relationLabels[p.relation]||'地点示意'}`);g.querySelector('.actor-name').textContent=p.name||p.factionName||p.factionId;g.querySelector('.actor-name').setAttribute('textLength',Math.min(224,(p.name||p.factionName||p.factionId).length*18));g.querySelector('.actor-name').setAttribute('lengthAdjust','spacingAndGlyphs');g.querySelector('.actor-members').textContent=p.characters.length?p.characters.join(' / '):'未具名小队';g.querySelector('.actor-relation').textContent=p.relation==='present'?'':relationLabels[p.relation];}
 previous=new Map(layout.map(p=>[p.key,p]));return layout;
 }
